insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'motion-forces', 'Projectile motion: Displacement in polar coordinates', 'The parabolic trajectory of a projectile can also be expressed in polar coordinates instead of Cartesian coordinates. In this case, the position has the general formula In this equation, the origin is the midpoint of the horizontal range of the projectile, and if the ground is flat, the parabolic arc is plotted in the range . This expression can be obtained by transforming the Cartesian equation as stated above by', 'Wikipedia: Projectile motion', 'https://en.wikipedia.org/w/index.php?title=Projectile_motion&oldid=1377746192', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
