insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'motion-forces', 'Projectile motion: Time of flight or total time of the whole journey', 'The total time t for which the projectile remains in the air is called the time-of-flight. The y-component of the trajectory is After the flight, the projectile returns to the horizontal axis (x-axis), so Note, we want the positive square root in this instance. Assuming the projectile starts from 0 ( If the starting point is at height y0 with respect to the point of impact, the time of flight is: e. g. for an object dropped from (vertical) rest at a height This result is independent of any initial horizontal velocity, as illustrated in the animation above.', 'Wikipedia: Projectile motion', 'https://en.wikipedia.org/w/index.php?title=Projectile_motion&oldid=1377746192', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'motion-forces' and body = 'The total time t for which the projectile remains in the air is called the time-of-flight. The y-component of the trajectory is After the flight, the projectile returns to the horizontal axis (x-axis), so Note, we want the positive square root in this instance. Assuming the projectile starts from 0 ( If the starting point is at height y0 with respect to the point of impact, the time of flight is: e. g. for an object dropped from (vertical) rest at a height This result is independent of any initial horizontal velocity, as illustrated in the animation above.');
